from math import prod

def ratio(d,w):
 q=[d*x/sum(w) for x in w]; b=list(map(int,q)); r=d-sum(b)
 for i in sorted(range(len(b)),key=lambda i:-(q[i]-b[i]))[:r]: b[i]+=1
 return b

def step(ch, mem, sd=0, ss=0, od=0, os=0, recon=0,t=1):
 s=ratio(ch,mem); a=[(sd if m else 0)+ss*x//ch for x,m in zip(s,mem)]; o=[(od if m else 0)+t*os*x//ch+recon*x//ch for x,m in zip(s,mem)]; return s,a,o,[x+y for x,y in zip(a,o)]
